<?php
declare(strict_types=1);
require_once __DIR__ . '/../../api/config/admin-authorization.php';
narrrfs_require_admin_request('owner_control.lab_store_drafts.ui.v1');
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Owner Control — Private Lab Store Drafts</title><style>
body{font-family:system-ui;background:#111820;color:#f4f7fb;padding:24px}main{max-width:1100px;margin:auto}.grid{display:grid;gap:14px;grid-template-columns:repeat(auto-fit,minmax(260px,1fr))}.card,form,section{background:#1b2530;border:1px solid #33404c;border-radius:12px;padding:16px;margin:14px 0}label{display:block;margin:8px 0}input,textarea,button,select{width:100%;box-sizing:border-box;padding:9px}button{margin-top:10px}.muted{color:#b8c6d2}.notice{min-height:1.5em}.source-result{display:flex;gap:8px;align-items:center;justify-content:space-between;border-top:1px solid #33404c;padding:8px 0}.source-result button{width:auto;margin:0}.preview{max-width:160px;max-height:120px;display:block;margin-top:8px}.hidden{display:none}
</style></head><body><main>
<a href="/owner-control/v1/index.php">← Owner Control</a><h1>Private Lab Store Draft Workspace</h1><p class="muted">Draft proposals only. No publish, live offer, purchase, inventory, fulfillment, economy, or progression action.</p><p id="status" class="notice" role="status">Loading…</p>
<label>Filter private drafts <input id="draft_filter" placeholder="Filter loaded drafts"></label><section id="list" class="grid"></section>
<section><h2>Approved source picker</h2><p class="muted">Read-only picker. Selecting a source fills only private draft proposal metadata; it never changes catalog, stock, prices, offers, ownership, or fulfillment.</p><label>Source type <select id="source_search_type"><option value="normal_store">Normal Store item</option><option value="genetic_item">Genetic Item</option></select></label><label>Search approved source <input id="source_query" minlength="2" maxlength="80" placeholder="At least two characters"></label><button type="button" id="source_search">Search approved source</button><div id="source_results"></div><p id="selected_source" class="muted">No source selected; manual reference remains available.</p><button type="button" id="clear_source">Clear selected source</button><img id="source_preview" class="preview hidden" alt="Selected source preview"></section>
<form id="form"><input id="draft_id" type="hidden"><input id="expected_version" type="hidden"><h2 id="form_heading">Create private draft</h2><label>Title <input id="title" required></label><label>Category <input id="category" required></label><label>Description <textarea id="description" required></textarea></label><label>Media reference (same-origin, draft only; manual fallback) <input id="media_reference"></label><label>Proposed source type (private draft) <select id="proposed_source_type"><option value="">Unavailable</option><option value="normal_store">normal_store</option><option value="genetic_item">genetic_item</option></select></label><label>Proposed source reference (private draft) <input id="proposed_source_item_id" type="number" min="1"></label><label>Proposed LP price (private draft) <input id="proposed_lp_price" type="number" min="0"></label><label>Proposed DSPOINC price (private draft) <input id="proposed_dspoinc_price" type="number" min="0"></label><label>Proposed stock (private draft) <input id="proposed_stock" type="number" min="0"></label><button>Save private draft</button></form>
</main><script>
'use strict';
const ids=['title','category','description','media_reference','proposed_source_type','proposed_source_item_id','proposed_lp_price','proposed_dspoinc_price','proposed_stock'],list=document.getElementById('list'),status=document.getElementById('status'),form=document.getElementById('form'),draftFilter=document.getElementById('draft_filter'),sourceResults=document.getElementById('source_results'),sourcePreview=document.getElementById('source_preview'),selectedSource=document.getElementById('selected_source');let pending=null,loadedDrafts=[];
function val(id){return document.getElementById(id).value} function set(id,v){document.getElementById(id).value=v??''} function payload(){const p={title:val('title'),category:val('category'),description:val('description'),media_reference:val('media_reference')||null,proposed_source_type:val('proposed_source_type')||null,proposed_source_item_id:val('proposed_source_item_id')?Number(val('proposed_source_item_id')):null,proposed_lp_price:val('proposed_lp_price')?Number(val('proposed_lp_price')):null,proposed_dspoinc_price:val('proposed_dspoinc_price')?Number(val('proposed_dspoinc_price')):null,proposed_stock:val('proposed_stock')?Number(val('proposed_stock')):null};if(val('draft_id')){p.draft_id=Number(val('draft_id'));p.expected_version=Number(val('expected_version'))}return p} function fingerprint(p){return JSON.stringify(p)} function keyFor(p){const f=fingerprint(p);if(!pending||pending.fingerprint!==f)pending={fingerprint:f,key:crypto.randomUUID().replaceAll('-','')+crypto.randomUUID().replaceAll('-','')};return pending.key}
function safePreview(ref){sourcePreview.classList.add('hidden');sourcePreview.removeAttribute('src');if(!ref)return;sourcePreview.src=ref;sourcePreview.onerror=()=>{sourcePreview.classList.add('hidden');selectedSource.textContent+=' Media unavailable.'};sourcePreview.classList.remove('hidden')}
function show(d){ids.forEach(k=>set(k,d[k]));set('draft_id',d.draft_id);set('expected_version',d.version);document.getElementById('form_heading').textContent='Edit private draft';pending=null;selectedSource.textContent=d.proposed_source_type&&d.proposed_source_item_id?'Selected private proposal: '+d.proposed_source_type+' #'+d.proposed_source_item_id:'No source selected; manual reference remains available.';safePreview(d.media_reference)}
async function openDraft(id){const r=await fetch('/api/owner-control/v1/lab-store/draft-details.php?draft_id='+encodeURIComponent(id),{credentials:'same-origin',cache:'no-store'}),p=await r.json();if(!r.ok||!p.success)throw Error();show(p.draft);status.textContent='Private draft loaded for editing.'}
function renderDrafts(){const q=draftFilter.value.trim().toLowerCase();list.replaceChildren();loadedDrafts.filter(d=>!q||[d.title,d.category,d.proposed_source_type].join(' ').toLowerCase().includes(q)).forEach(d=>{const c=document.createElement('article');c.className='card';const h=document.createElement('strong');h.textContent=d.title+' — private draft';const m=document.createElement('p');m.textContent=(d.proposed_source_type||'proposal unavailable')+' · LP/DSPOINC/stock proposal fields are private metadata';const b=document.createElement('button');b.type='button';b.textContent='Open details / Edit';b.onclick=()=>openDraft(d.draft_id).catch(()=>status.textContent='Details unavailable.');c.append(h,m,b);list.append(c)});if(!list.childElementCount)list.textContent='No matching private drafts.'}
async function load(){const r=await fetch('/api/owner-control/v1/lab-store/drafts.php',{credentials:'same-origin',cache:'no-store'}),p=await r.json();if(!r.ok||!p.success)throw Error();loadedDrafts=p.drafts;renderDrafts();status.textContent=p.drafts.length?'Private drafts loaded.':'No private drafts yet.'}
async function searchSources(){const type=val('source_search_type'),q=val('source_query').trim();if(q.length<2){status.textContent='Enter at least two characters for the read-only source search.';return}const r=await fetch('/api/owner-control/v1/lab-store/draft-sources.php?type='+encodeURIComponent(type)+'&q='+encodeURIComponent(q),{credentials:'same-origin',cache:'no-store'}),p=await r.json();if(!r.ok||!p.success)throw Error();sourceResults.replaceChildren();p.items.forEach(item=>{const row=document.createElement('div'),label=document.createElement('span'),choose=document.createElement('button');row.className='source-result';label.textContent=item.title+' · '+item.source_state;choose.type='button';choose.textContent='Use private proposal';choose.onclick=()=>{set('proposed_source_type',item.source_type);set('proposed_source_item_id',item.source_item_id);selectedSource.textContent='Selected private proposal: '+item.title+' ('+item.source_type+' #'+item.source_item_id+').';safePreview(item.presentation_ref);pending=null};row.append(label,choose);sourceResults.append(row)});if(!p.items.length)sourceResults.textContent='No approved sources found.'}
document.getElementById('source_search').onclick=()=>searchSources().catch(()=>status.textContent='Approved source search unavailable.');document.getElementById('clear_source').onclick=()=>{set('proposed_source_type','');set('proposed_source_item_id','');selectedSource.textContent='No source selected; manual reference remains available.';safePreview(null);pending=null};draftFilter.addEventListener('input',renderDrafts);ids.forEach(id=>document.getElementById(id).addEventListener('input',()=>{if(pending&&pending.fingerprint!==fingerprint(payload()))pending=null}));
form.onsubmit=async e=>{e.preventDefault();const p=payload(),editing=Boolean(p.draft_id);p.idempotency_key=keyFor(p);status.textContent='Saving private draft…';try{const a=editing?'update':'create',cr=await fetch('/api/owner-control/v1/lab-store/draft-csrf.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:a})}),ct=await cr.json(),r=await fetch(editing?'/api/owner-control/v1/lab-store/draft-update.php':'/api/owner-control/v1/lab-store/draft-create.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':ct.csrf_token},body:JSON.stringify(p)}),out=await r.json();if(r.status===409&&out.error==='version_conflict')throw Error('version_conflict');if(!r.ok||!out.success)throw Error();pending=null;status.textContent='Private draft saved.';await load()}catch(x){status.textContent=x.message==='version_conflict'?'Version conflict: reload details before saving.':'Private draft save failed; retry unchanged data to reuse its idempotency key.'}};load().catch(()=>status.textContent='Private drafts unavailable.');
</script></body></html>
